    { const char * tb_v312 = "// экран 80×25: байт буквы и байт цвета; русские буквы рисуем своим шрифтом (см. tb_vga_font)\n"; *(const char * *)tb_grow(v_lines) = tb_v312; }
    { const char * tb_v313 = "TB_API volatile unsigned short *const tb_vga = (volatile unsigned short *)0xB8000;\n"; *(const char * *)tb_grow(v_lines) = tb_v313; }
    { const char * tb_v314 = "TB_API int tb_vrow = 0, tb_vcol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v314; }
    { const char * tb_v315 = "TB_API unsigned char tb_vcolor = 0x0A;   // светло-зелёный на чёрном\n"; *(const char * *)tb_grow(v_lines) = tb_v315; }
    { const char * tb_v316 = "TB_API void tb_vga_put(unsigned char ch) {\n"; *(const char * *)tb_grow(v_lines) = tb_v316; }
    { const char * tb_v317 = "    if (ch == '\\n') { tb_vcol = 0; tb_vrow++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v317; }
    { const char * tb_v318 = "    else if (ch == '\\b') { if (tb_vcol > 0) tb_vcol--; tb_vga[tb_vrow * 80 + tb_vcol] = (unsigned short)(tb_vcolor << 8 | ' '); }\n"; *(const char * *)tb_grow(v_lines) = tb_v318; }
    { const char * tb_v319 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v319; }
