    { const char * tb_v1156 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1156; }
    { const char * tb_v1157 = "// список: кусок памяти, len элементов по size байт, место на cap\n"; *(const char * *)tb_grow(v_lines) = tb_v1157; }
