    { const char * tb_v1412 = "// --llvm: то же через указатель (из файла .ll так проще, чем отдавать struct по значению)\n"; *(const char * *)tb_grow(v_lines) = tb_v1412; }
    { const char * tb_v1413 = "TB_INL void tb_temp_begin_p(tb_mark *m) { *m = tb_temp_begin(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1413; }
