    { const char * tb_v2798 = "// together: шаг 1 — просим память принести место ключа заранее\n"; *(const char * *)tb_grow(v_lines) = tb_v2798; }
    { const char * tb_v2799 = "TB_INL unsigned long long tb_dpre1(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2799; }
    { const char * tb_v2800 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2800; }
