    { const char * tb_v5273 = "// CGBitmapContextCreateImage делал копию при записи: каждая новая точка в кадре\n"; *(const char * *)tb_grow(v_lines) = tb_v5273; }
    { const char * tb_v5274 = "// стоила копии страницы памяти. Теперь три своих буфера по кругу: кадр копируется\n"; *(const char * *)tb_grow(v_lines) = tb_v5274; }
    { const char * tb_v5275 = "// одним memcpy, а картинка смотрит прямо в буфер, без копий внутри системы.\n"; *(const char * *)tb_grow(v_lines) = tb_v5275; }
