    { const char * tb_v5281 = "// ---------- Metal (Mac) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5281; }
    { const char * tb_v5282 = "// Metal зовём так же, как Cocoa: через objc_msgSend. Шейдер (tb_msl выше, compiler/gpu/tb.metal)\n"; *(const char * *)tb_grow(v_lines) = tb_v5282; }
    { const char * tb_v5283 = "// Mac переводит сам при запуске. Сама библиотека Metal грузится через dlopen: нет её — процессор.\n"; *(const char * *)tb_grow(v_lines) = tb_v5283; }
    { const char * tb_v5284 = "extern void *objc_autoreleasePoolPush(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v5284; }
