    { const char * tb_v5319 = "// свой кадр на видеокарте размером tb_gw × tb_gh\n"; *(const char * *)tb_grow(v_lines) = tb_v5319; }
    { const char * tb_v5320 = "TB_API id tb_mtl_texture(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5320; }
