    { const char * tb_v6068 = "    for (int i = 0; i < 6; i++) if (t[i] < -8192 || t[i] > 8192) big = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6068; }
    { const char * tb_v6069 = "    if (!big) { tb_tri_draw_i(t, c, 0); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6069; }
    { const char * tb_v6070 = "    double px[3] = { (double)x1, (double)x2, (double)x3 }, py[3] = { (double)y1, (double)y2, (double)y3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v6070; }
