    { const char * tb_v6072 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6072; }
    { const char * tb_v6073 = "// картинка из load_image: левый верхний угол в (x, y); прозрачные точки (меньше 128) не рисуются\n"; *(const char * *)tb_grow(v_lines) = tb_v6073; }
    { const char * tb_v6074 = "TB_API void tb_draw_image(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6074; }
    { const char * tb_v6075 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6075; }
    { const char * tb_v6076 = "    if (tb_gpu_on) tb_gpu_image(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v6076; }
    { const char * tb_v6077 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6077; }
    { const char * tb_v6078 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v6078; }
    { const char * tb_v6079 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v6079; }
    { const char * tb_v6080 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6080; }
    { const char * tb_v6081 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v6081; }
    { const char * tb_v6082 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6082; }
    { const char * tb_v6083 = "            uint32_t v = src[j * im->w + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6083; }
    { const char * tb_v6084 = "            if ((v >> 24) >= 128) tb_px[(y + j) * tb_gw + x + i] = v & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v6084; }
    { const char * tb_v6085 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6085; }
    { const char * tb_v6086 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6086; }
    { const char * tb_v6087 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6087; }
    { const char * tb_v6088 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v6088; }
    { const char * tb_v6089 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6089; }
    { const char * tb_v6090 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6090; }
    { const char * tb_v6091 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6091; }
    { const char * tb_v6092 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v6092; }
    { const char * tb_v6093 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v6093; }
    { const char * tb_v6094 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6094; }
    { const char * tb_v6095 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6095; }
    { const char * tb_v6096 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v6096; }
    { const char * tb_v6097 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6097; }
    { const char * tb_v6098 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v6098; }
    { const char * tb_v6099 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v6099; }
    { const char * tb_v6100 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6100; }
    { const char * tb_v6101 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v6101; }
    { const char * tb_v6102 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v6102; }
    { const char * tb_v6103 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v6103; }
    { const char * tb_v6104 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6104; }
    { const char * tb_v6105 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6105; }
    { const char * tb_v6106 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v6106; }
    { const char * tb_v6107 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v6107; }
    { const char * tb_v6108 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v6108; }
    { const char * tb_v6109 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v6109; }
    { const char * tb_v6110 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v6110; }
    { const char * tb_v6111 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v6111; }
    { const char * tb_v6112 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v6112; }
    { const char * tb_v6113 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6113; }
    { const char * tb_v6114 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v6114; }
    { const char * tb_v6115 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6115; }
    { const char * tb_v6116 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6116; }
    { const char * tb_v6117 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6117; }
    { const char * tb_v6118 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v6118; }
