    { const char * tb_v6148 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6148; }
    { const char * tb_v6149 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6149; }
    { const char * tb_v6150 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6150; }
    { const char * tb_v6151 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v6151; }
