    { const char * tb_v6153 = "    for (int i = 0; i < 3; i++) { h ^= w[i]; h *= 1099511628211ULL; h ^= h >> 29; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6153; }
    { const char * tb_v6154 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6154; }
    { const char * tb_v6155 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6155; }
