    { const char * tb_v6321 = "// деление с округлением вниз (b > 0); через числа без знака — одинаково на любой видеокарте\n"; *(const char * *)tb_grow(v_lines) = tb_v6321; }
    { const char * tb_v6322 = "TB_INL long long tb_fdiv(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6322; }
    { const char * tb_v6323 = "    return a >= 0 ? (long long)((unsigned long long)a / (unsigned long long)b)\n"; *(const char * *)tb_grow(v_lines) = tb_v6323; }
