    { const char * tb_v6325 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6325; }
    { const char * tb_v6326 = "// фокус экрана × 256 (угол обзора 60°)\n"; *(const char * *)tb_grow(v_lines) = tb_v6326; }
