    { const char * tb_v6328 = "// угол сетки p (× 4096) по записи r: место на экране (целые точки) и глубина D = 2^24 - 2^24 * zn / z, zn = 205 / 4096\n"; *(const char * *)tb_grow(v_lines) = tb_v6328; }
    { const char * tb_v6329 = "TB_INL void tb_m3_corner(const int32_t *r, const int32_t *p, long long f, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6329; }
    { const char * tb_v6330 = "    long long c[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v6330; }
    { const char * tb_v6331 = "    for (int k = 0; k < 3; k++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6331; }
    { const char * tb_v6332 = "        c[k] = (((long long)r[4 * k] * p[0] + (long long)r[4 * k + 1] * p[1] + (long long)r[4 * k + 2] * p[2]) >> 30) + r[4 * k + 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v6332; }
    { const char * tb_v6333 = "    o[0] = ((long long)tb_gw * 128 + tb_fdiv(f * c[0], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v6333; }
