    { const char * tb_v6357 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6357; }
    { const char * tb_v6358 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v6358; }
    { const char * tb_v6359 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6359; }
    { const char * tb_v6360 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6360; }
    { const char * tb_v6361 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v6361; }
    { const char * tb_v6362 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6362; }
    { const char * tb_v6363 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6363; }
    { const char * tb_v6364 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v6364; }
    { const char * tb_v6365 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v6365; }
    { const char * tb_v6366 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v6366; }
    { const char * tb_v6367 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6367; }
    { const char * tb_v6368 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6368; }
    { const char * tb_v6369 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v6369; }
    { const char * tb_v6370 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6370; }
    { const char * tb_v6371 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6371; }
    { const char * tb_v6372 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v6372; }
    { const char * tb_v6373 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v6373; }
    { const char * tb_v6374 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6374; }
    { const char * tb_v6375 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6375; }
    { const char * tb_v6376 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v6376; }
    { const char * tb_v6377 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6377; }
    { const char * tb_v6378 = "    return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v6378; }
